mapper.insert:

    SELECT SEQ_HIST_EVENT.NEXTVAL FROM DUAL

INSERT INTO HIST_EVENT (
      HIST_ID
    , ENTITY_TYPE
    , TABLE_NM
    , ENTITY_ID
    , ACTION_TYPE
    , ACTOR_ID
    , ACTOR_NM
    , REASON
    , REQ_IP
    , TRACE_ID
    , CHANGED_AT
) VALUES (
      #{hist_id}
    , #{entity_type}
    , #{table_nm}
    , #{entity_id}
    , #{action_type}
    , #{actor_id}
    , #{actor_nm}
    , #{reason}
    , #{req_ip}
    , #{trace_id}
    , SYSTIMESTAMP
)

INSERT INTO HIST_SNAPSHOT (
      HIST_ID
    , BEFORE_DATA
    , AFTER_DATA
) VALUES (
      #{hist_id}
    , #{before_data}
    , #{after_data}
)
